// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    // A minimal recording callee that exposes the exact function selector transfer expects:
    // function transferFrom(address,address,uint256)
    // We will make it succeed always; the distinction between true/false return of C is independent
    // of callee behaviour here, since both reference and mutant complete without revert and only differ
    // in the final return value. We still deploy a valid callee so the low-level call succeeds and is
    // observable if needed.
    function setUp() public { c = new demo(); }

    // Fuzzed params: an address 'from', an address 'callee', a single-element array length selector value
    // and a uint256 v. We cannot pass dynamic arrays directly as fuzz parameters, so we fuzz the recipient
    // address and construct a single-element array in the test. This keeps the domain wide.
    function testFuzz_property(address from, address callee, uint256 v) public {
        // admissible domain: _tos.length must be > 0 (we construct length 1), and callee must be non-zero
        vm.assume(callee != address(0));

        // Deploy a helper that matches the called function signature so the low-level call succeeds and is well-formed.
        Recorder rec = new Recorder();

        // Use the recorder's address as the callee to ensure the call succeeds and is recorded.
        address target = address(rec);

        // Construct single-element _tos array
        address[] memory tos = new address[](1);
        tos[0] = callee; // fuzzed recipient address (could be any address)

        // The call inside C will do: caddress.call(abi.encodeWithSelector(id, from, _tos[i], v))
        // where id = transferFrom(address,address,uint256)
        // The recorder implements that function and will record what it received.

        // Make the call and capture whether it returned (ok) and also capture the returned bool
        bool ok;
        bool ret;
        try c.transfer(from, target, tos, v) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // GENERAL RULE (single assert): For any admissible inputs where transfer does not revert (ok == true),
        // the reference implementation always returns true. The mutant changes the final returned value to false
        // while still not reverting, so it will violate this property for some inputs. We assert that if the call
        // completed then the returned bool is true.
        assertTrue(!ok || ret);
    }
}

// A minimal recorder that implements the exact signature called by C so the low-level call is decoded and recorded.
contract Recorder {
    event Called(address indexed from, address indexed to, uint256 v);

    // match selector: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Called(from, to, v);
        return true;
    }
}
